        { "text", text = "|cOXP_FRIENDLY_Bath'rah the Windwatcher|r camps in the ruins of the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills." },
        { "goto", x = 80.5, y = 66.92, zone = "1416" },
