      { only = "Shaman", source = "polestar:forever/class/shaman/spirit-totem",
        { "text", text = "The Sunken Temple" },
        { "text", text = "A five-player dungeon: needs a group of five, about level 50-55. Fly to Stonard and ride east. The Sunken Temple (Temple of Atal'Hakkar) stands in the middle of the Pool of Tears: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and |cOXP_FRIENDLY_Zul'Lor|r the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others (Renew, a |cOXP_FRIENDLY_Healing Ward|r): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys." },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 1, quest = 8413, text = "Amber Voodoo Feather: 2 (|cOXP_LOOT_Amber Voodoo Feather|r: Gasher, |cOXP_FRIENDLY_Zul'Lor|r)" },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 2, quest = 8413, text = "Blue Voodoo Feather: 2 (|cOXP_LOOT_Blue Voodoo Feather|r: Hukku, Mijan)" },
        { "goto", x = 69.9, y = 53.6, zone = "1435" },
        { "complete", obj = 3, quest = 8413, text = "Green Voodoo Feather: 2 (|cOXP_LOOT_Green Voodoo Feather|r: Zolo, Loro)" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/spirit-totem",
